 2 lagostas (para a versão de luxo) cozinhadas ou cruas &#13;
 800g de camarão cozido &#13;
 &#13;
&#13;
 Molho : &#13;
&#13;
 &#13;
 1 ovo &#13;
 1 colher de chá de mostarda &#13;
 200ml de óleo &#13;
 sumo de meio limão &#13;
 100ml de creme completo &#13;
 1 talo de aipo &#13;
 sal, pimenta &#13;
 &#13;
 Instructions : &#13;
&#13;
&#13;
   &#13;
&#13;
